const $=id=>document.getElementById(id);let current;const labels={open:'OPEN',close:'CLOSE',both:'CLOSE + OPEN',hold:'KEEP OPEN',proof:'PROOF',cta:'CTA'};const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function cards(){let q=$('search').value.toLowerCase(),matches=videos.filter(v=>(v.title+' '+v.product+' '+v.format).toLowerCase().includes(q));$('count').textContent=matches.length===videos.length?String(videos.length).padStart(2,'0'):matches.length+' / '+videos.length;$('cards').innerHTML=matches.map(v=>`<button class="card ${v.id===current?.id?'active':''}" data-id="${v.id}" aria-pressed="${v.id===current?.id}"><span class="card-index">${String(videos.indexOf(v)+1).padStart(2,'0')}</span><span class="card-copy"><small>${esc(v.product)} · ${esc(v.duration)}</small><strong>${esc(v.title)}</strong><span class="card-format">${esc(v.format)}</span></span><span class="card-arrow" aria-hidden="true">↗</span></button>`).join('')||'<p class="empty">No examples match. Try another product or format.</p>';document.querySelectorAll('.card').forEach(b=>b.onclick=()=>{location.hash=b.dataset.id});}
function select(){current=videos.find(v=>v.id===location.hash.slice(1))||videos[0];$('format').textContent=current.format;$('title').textContent=current.title;$('summary').textContent=current.summary;$('analysis-basis').textContent=current.basis||'Approximate recording timestamps. Based on visuals and on-screen captions; viewer thoughts are possible reactions. Product statements are the creator’s claims. Some recordings briefly repeat their opening.';$('lesson').textContent=current.lesson;$('sequence').innerHTML=current.sequence.map((s,i)=>`<li class="sequence-stage" style="${plannerStageColour(i)};--name-colour:${structureColour(i).ink}">${esc(s)}</li>`).join('');$('player').pause();$('player').src=`media/${current.id}.mp4`;$('media-status').textContent='Loading recording…';$('copy-fallback').hidden=true;$('player').playbackRate=Number($('speed').value);$('rows').innerHTML=current.rows.map((r,i)=>`<tr data-index="${i}"><td><button class="time" data-time="${r[0]}" aria-label="Play from ${r[0]} seconds">${r[0]}–${r[1]}s</button></td><td>${esc(r[2])}</td><td class="thought">“${esc(r[3])}”</td><td><span class="badge ${r[4]}">${labels[r[4]]}</span><br>${esc(r[5])}</td></tr>`).join('');document.querySelectorAll('.time').forEach(b=>b.onclick=()=>{setWorkspaceView('watch');seekVideo(Number(b.dataset.time));$('player').scrollIntoView({behavior:'smooth',block:'center'})});try{$('notes').value=localStorage.getItem('playbook-notes-'+current.id)||'';$('saved').textContent='';}catch{$('notes').value='';$('saved').textContent='Browser saving unavailable';}renderPlanner();resetLearning();resetTracker();cards();setWorkspaceView(workspaceView);document.title=current.title+' | Kieron’s Video Playbook';}
$('search').oninput=cards;window.onhashchange=()=>{if(videos.some(v=>v.id===location.hash.slice(1))&&current.id!==location.hash.slice(1))select();};$('speed').onchange=()=>{$('player').playbackRate=Number($('speed').value)};$('player').ontimeupdate=()=>{let t=$('player').currentTime;updateTracker(t);document.querySelectorAll('#rows tr').forEach((tr,i)=>tr.classList.toggle('playing',$('follow').checked&&t>=current.rows[i][0]&&t<current.rows[i][1]));};$('follow').onchange=()=>$('player').ontimeupdate();$('notes').oninput=()=>{try{localStorage.setItem('playbook-notes-'+current.id,$('notes').value);$('saved').textContent='Saved on this device';}catch{$('saved').textContent='Unable to save—download your notes';}};$('print').onclick=()=>window.print();$('export').onclick=()=>{let content=videos.map(v=>{let n='';try{n=localStorage.getItem('playbook-notes-'+v.id)||'';}catch{}return v.title+' — '+v.format+'\n\n'+(n||'(No notes yet)')}).join('\n\n-------------------\n\n');let url=URL.createObjectURL(new Blob([content],{type:'text/plain'}));let a=document.createElement('a');a.href=url;a.download='kieron-video-playbook-notes.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};select();

$('planner-product').oninput=savePlanner;$('planner-angle').oninput=savePlanner;
$('copy-planner').onclick=()=>copyPlanner(false);$('copy-blank').onclick=()=>copyPlanner(true);
$('planner-jump').onclick=e=>{e.preventDefault();setWorkspaceView('write');$('script-planner').scrollIntoView({behavior:'smooth',block:'start'});};
$('download-planner').onclick=()=>{const url=URL.createObjectURL(new Blob([plannerMarkdown()],{type:'text/markdown'}));const a=document.createElement('a');a.href=url;a.download=current.id+'-script-planner.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};

function openLearning(){setWorkspaceView('practise');const p=$('learn-panel');p.hidden=false;$('learn-toggle').setAttribute('aria-expanded','true');$('learn-toggle').textContent='Close practice ↑';$('learn-zone').scrollIntoView({behavior:'smooth',block:'start'});}
$('learn-jump').onclick=openLearning;
$('learn-toggle').onclick=()=>{if($('learn-panel').hidden)openLearning();else{$('learn-panel').hidden=true;$('learn-toggle').setAttribute('aria-expanded','false');$('learn-toggle').textContent='Start practising ↓';}};
$('learn-cards-mode').onclick=()=>{learnMode='cards';renderLearning();};
$('learn-test-mode').onclick=startLearnTest;

setupWorkspace();
